DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM body_leads WHERE campaign='bodymestory-workbook-7-days' AND email='qa@example.invalid') OR EXISTS(SELECT 1 FROM body_lead_events WHERE id IN('b0d10002-0000-4000-8000-000000000001'::uuid,'b0d10002-0000-4000-8000-000000000002'::uuid)) OR EXISTS(SELECT 1 FROM body_lead_rate_limits WHERE bucket IN('ip:dd8ac639bda2e4946ff4966807dee07bf772a56f83a98ce282fa07337bb168c9','email:4ec4b05a7cd5d25a08d98eb74f0ce5a3be52c03fa96b36b94d38c70dac240801')) THEN RAISE EXCEPTION 'Bodymestory QA fixture already exists; use a fresh isolated test branch'; END IF;
