DO $$
DECLARE lead_row body_leads%ROWTYPE; n integer;
BEGIN
 SELECT count(*) INTO n FROM body_leads WHERE campaign='bodymestory-workbook-7-days' AND email='qa@example.invalid';
 IF n<>1 THEN RAISE EXCEPTION 'Expected exactly 1 lead, found %',n; END IF;
 SELECT * INTO STRICT lead_row FROM body_leads WHERE campaign='bodymestory-workbook-7-days' AND email='qa@example.invalid';
 IF lead_row.id<>'b0d10001-0000-4000-8000-000000000001'::uuid OR lead_row.name<>'QA fixture only' THEN RAISE EXCEPTION 'Upsert changed stable lead ID or erased existing optional name'; END IF;
 IF lead_row.first_source<>'facebook' OR lead_row.last_source<>'manychat' OR lead_row.first_episode<>'RG01' OR lead_row.last_episode<>'RG12' THEN RAISE EXCEPTION 'First/last attribution not preserved'; END IF;
 IF lead_row.first_utm<>'{"utm_source":"facebook","utm_medium":"comment","utm_campaign":"bodymestory_7days","utm_content":"RG01"}'::jsonb OR lead_row.last_utm<>'{"utm_source":"facebook","utm_medium":"dm","utm_campaign":"bodymestory_7days","utm_content":"RG12"}'::jsonb THEN RAISE EXCEPTION 'First/last UTM attribution mismatch'; END IF;
 IF lead_row.created_at<>'2026-11-01T00:00:00.000Z'::timestamptz OR lead_row.updated_at<>'2026-11-01T00:30:00.000Z'::timestamptz THEN RAISE EXCEPTION 'First/latest timestamps incorrect'; END IF;
 IF lead_row.marketing_consent_at IS DISTINCT FROM '2026-11-01T00:00:00.000Z'::timestamptz OR lead_row.ads_consent_at IS DISTINCT FROM '2026-11-01T00:00:00.000Z'::timestamptz OR lead_row.marketing_consent_version IS DISTINCT FROM '2026-11-01-bodymestory-v1' OR lead_row.ads_consent_version IS DISTINCT FROM '2026-11-01-bodymestory-v1' THEN RAISE EXCEPTION 'Unchecked defaults incorrectly erased prior explicit consent'; END IF;
 IF lead_row.privacy_acknowledged_at<>'2026-11-01T00:30:00.000Z'::timestamptz OR lead_row.privacy_version<>'2026-11-01-bodymestory-v1' THEN RAISE EXCEPTION 'Latest privacy acknowledgment incorrect'; END IF;
 SELECT count(*) INTO n FROM body_lead_events WHERE lead_id=lead_row.id;
 IF n<>2 THEN RAISE EXCEPTION 'Expected 2 lead events, found %',n; END IF;
 IF NOT EXISTS(SELECT 1 FROM body_lead_events WHERE id='b0d10002-0000-4000-8000-000000000001'::uuid AND lead_id=lead_row.id AND campaign='bodymestory-workbook-7-days' AND marketing_consent=TRUE AND ads_consent=TRUE AND source='facebook' AND episode='RG01' AND occurred_at='2026-11-01T00:00:00.000Z'::timestamptz AND payload_hash='cfb98a4b98796680f9bd983f5bbed45345142856e06d3c7930db84f691c64d76') THEN RAISE EXCEPTION 'First consent event missing or incorrect'; END IF;
 IF NOT EXISTS(SELECT 1 FROM body_lead_events WHERE id='b0d10002-0000-4000-8000-000000000002'::uuid AND lead_id=lead_row.id AND campaign='bodymestory-workbook-7-days' AND marketing_consent=FALSE AND ads_consent=FALSE AND source='manychat' AND episode='RG12' AND occurred_at='2026-11-01T00:30:00.000Z'::timestamptz AND payload_hash='2176326759e23a0b967650812408e74a83422a9288d5b8c736e9024a02857fb0') THEN RAISE EXCEPTION 'Second consent event missing or incorrect'; END IF;
 IF (SELECT count(DISTINCT id) FROM body_lead_events WHERE lead_id=lead_row.id AND id IS NOT NULL)<>2 THEN RAISE EXCEPTION 'Event IDs are empty or not unique'; END IF;
END $$;

DO $$ BEGIN
 IF (SELECT count(*) FROM body_lead_rate_limits WHERE bucket IN('ip:dd8ac639bda2e4946ff4966807dee07bf772a56f83a98ce282fa07337bb168c9','email:4ec4b05a7cd5d25a08d98eb74f0ce5a3be52c03fa96b36b94d38c70dac240801') AND hits=6 AND expires_at='2026-11-01T01:00:00Z'::timestamptz)<>2 THEN RAISE EXCEPTION 'Rate limit counter or fixed-window expiry incorrect'; END IF;
 IF NOT EXISTS(SELECT 1 FROM body_lead_rate_limits WHERE bucket='email:4ec4b05a7cd5d25a08d98eb74f0ce5a3be52c03fa96b36b94d38c70dac240801' AND hits>5) OR NOT EXISTS(SELECT 1 FROM body_lead_rate_limits WHERE bucket='ip:dd8ac639bda2e4946ff4966807dee07bf772a56f83a98ce282fa07337bb168c9' AND hits<=10) THEN RAISE EXCEPTION 'Email limit vs IP limit expectation incorrect'; END IF;
